package com.fitflow.recommendations;import java.util.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/recommendations") public class RecommendationController{private final RecommendationRepository repo;public RecommendationController(RecommendationRepository r){repo=r;}@GetMapping public Map<String,Object> list(@AuthenticationPrincipal Jwt jwt){return Map.of("recommendations",repo.findByUserIdOrderByCreatedAtDesc(jwt.getSubject()));}}

